"use client";

import {
  NewsletterForm,
  toUpdatePayload,
  type NewsletterFormValues,
} from "@/components/newsletter/NewsletterForm";
import { Badge } from "@/components/ui/badge";
import { Button } from "@/components/ui/button";
import {
  Dialog,
  DialogContent,
  DialogDescription,
  DialogFooter,
  DialogHeader,
  DialogTitle,
} from "@/components/ui/dialog";
import { Skeleton } from "@/components/ui/skeleton";
import { Spinner } from "@/components/ui/spinner";
import type { SerializedNewsletter } from "@/services/newsletter/newsletterService";
import { Trash2 } from "lucide-react";
import Link from "next/link";
import { useParams, useRouter } from "next/navigation";
import { useEffect, useState } from "react";
import { toast } from "sonner";

type LoadState =
  | { status: "loading" }
  | { status: "ready"; newsletter: SerializedNewsletter }
  | { status: "not-found" }
  | { status: "error"; message: string };

function toFormValues(newsletter: SerializedNewsletter): NewsletterFormValues {
  return {
    name: newsletter.name,
    scope: newsletter.scope,
    location: newsletter.location ?? "",
    coords:
      newsletter.latitude != null && newsletter.longitude != null
        ? { latitude: newsletter.latitude, longitude: newsletter.longitude }
        : null,
    categories: newsletter.categories,
    customQuery: newsletter.customQuery ?? "",
    storyCount: newsletter.storyCount,
    frequency: newsletter.frequency,
    sendTimeLocal: newsletter.sendTimeLocal,
    timezone: newsletter.timezone,
    // Placeholders for frequencies that don't use them; never sent unless used.
    dayOfWeek: newsletter.dayOfWeek ?? 1,
    dayOfMonth: newsletter.dayOfMonth ?? 1,
  };
}

async function readError(response: Response, fallback: string): Promise<string> {
  try {
    const payload = (await response.json()) as { error?: string };
    return payload.error ?? fallback;
  } catch {
    return fallback;
  }
}

function DeleteNewsletterButton({
  newsletterId,
  name,
}: {
  newsletterId: string;
  name: string;
}) {
  const router = useRouter();
  const [open, setOpen] = useState(false);
  const [deleting, setDeleting] = useState(false);

  async function confirmDelete() {
    setDeleting(true);
    try {
      const response = await fetch(`/api/newsletters/${newsletterId}`, {
        method: "DELETE",
      });
      // 404: already gone (e.g. deleted in another tab) — same end state.
      if (!response.ok && response.status !== 404) {
        throw new Error(await readError(response, "Could not delete newsletter"));
      }
      toast.success("Newsletter deleted");
      setOpen(false);
      router.push("/newsletters");
    } catch (err) {
      toast.error(err instanceof Error ? err.message : "Could not delete newsletter");
      setDeleting(false);
    }
  }

  return (
    <>
      <Button
        type="button"
        variant="destructive"
        className="w-full"
        onClick={() => setOpen(true)}
      >
        <Trash2 data-icon="inline-start" />
        Delete
      </Button>
      <Dialog
        open={open}
        onOpenChange={(next) => {
          if (!deleting) setOpen(next);
        }}
      >
        <DialogContent showCloseButton={!deleting}>
          <DialogHeader>
            <DialogTitle>Delete this newsletter?</DialogTitle>
            <DialogDescription>
              “{name}” will stop sending and its delivery history will be
              removed. This can’t be undone.
            </DialogDescription>
          </DialogHeader>
          <DialogFooter>
            <Button
              type="button"
              variant="outline"
              disabled={deleting}
              onClick={() => setOpen(false)}
            >
              Cancel
            </Button>
            <Button
              type="button"
              variant="destructive"
              disabled={deleting}
              onClick={confirmDelete}
            >
              {deleting ? (
                <Spinner data-icon="inline-start" />
              ) : (
                <Trash2 data-icon="inline-start" />
              )}
              {deleting ? "Deleting…" : "Delete newsletter"}
            </Button>
          </DialogFooter>
        </DialogContent>
      </Dialog>
    </>
  );
}

export default function EditNewsletterPage() {
  const params = useParams<{ newsletterId: string }>();
  const newsletterId = params.newsletterId;
  const router = useRouter();
  const [state, setState] = useState<LoadState>({ status: "loading" });

  useEffect(() => {
    const controller = new AbortController();
    setState({ status: "loading" });
    fetch(`/api/newsletters/${newsletterId}`, { signal: controller.signal })
      .then(async (response) => {
        if (response.status === 404) {
          setState({ status: "not-found" });
          return;
        }
        if (!response.ok) {
          throw new Error(await readError(response, "Could not load newsletter"));
        }
        const payload = (await response.json()) as {
          newsletter: SerializedNewsletter;
        };
        setState({ status: "ready", newsletter: payload.newsletter });
      })
      .catch((err: unknown) => {
        if (controller.signal.aborted) return;
        setState({
          status: "error",
          message: err instanceof Error ? err.message : "Could not load newsletter",
        });
      });
    return () => controller.abort();
  }, [newsletterId]);

  async function save(values: NewsletterFormValues) {
    const response = await fetch(`/api/newsletters/${newsletterId}`, {
      method: "PATCH",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify(toUpdatePayload(values)),
    });
    if (!response.ok) {
      throw new Error(await readError(response, "Could not save changes"));
    }
    toast.success("Newsletter updated");
    router.push("/newsletters");
  }

  const newsletter = state.status === "ready" ? state.newsletter : null;

  return (
    <div className="mx-auto w-full min-h-0 max-w-6xl px-4 pt-4 pb-28 md:px-6 lg:pb-10">
      <div className="mb-6 flex flex-col gap-1.5">
        <div className="flex items-center gap-2 text-sm text-muted-foreground">
          <span>/</span>
          <Link href="/newsletters" className="hover:text-foreground">
            Newsletters
          </Link>
          <span>/</span>
          <span className="text-foreground">Edit</span>
        </div>
        <div className="flex flex-wrap items-center gap-3">
          <h1 className="font-display text-3xl font-semibold tracking-tight">
            {newsletter ? newsletter.name : "Edit newsletter"}
          </h1>
          {newsletter ? (
            <Badge variant={newsletter.isActive ? "secondary" : "outline"}>
              {newsletter.isActive ? "Active" : "Paused"}
            </Badge>
          ) : null}
        </div>
        <p className="max-w-xl text-sm text-muted-foreground">
          Changes apply from the next email. Changing the schedule moves the
          next send.
        </p>
      </div>

      {state.status === "loading" ? (
        <div className="grid grid-cols-1 gap-6 lg:grid-cols-[minmax(0,1fr)_20rem]">
          <Skeleton className="h-[36rem] rounded-xl" />
          <Skeleton className="h-80 rounded-xl" />
        </div>
      ) : null}

      {state.status === "not-found" || state.status === "error" ? (
        <div className="rounded-xl border px-6 py-12 text-center">
          <p className="text-sm text-muted-foreground">
            {state.status === "not-found"
              ? "This newsletter doesn’t exist or was deleted."
              : state.message}
          </p>
          <Link
            href="/newsletters"
            className="mt-4 inline-flex h-9 items-center rounded-md border px-4 text-sm"
          >
            Back to newsletters
          </Link>
        </div>
      ) : null}

      {newsletter ? (
        <NewsletterForm
          // Remount if a different newsletter loads into this page.
          key={newsletter.id}
          formId="edit-newsletter-form"
          initialValues={toFormValues(newsletter)}
          email={newsletter.email}
          emailBadge="Saved address"
          submitLabel="Save changes"
          submittingLabel="Saving…"
          nextSendLabel="Next email"
          paused={!newsletter.isActive}
          requireChanges
          onSubmit={save}
          secondaryAction={
            <DeleteNewsletterButton
              newsletterId={newsletter.id}
              name={newsletter.name}
            />
          }
        />
      ) : null}
    </div>
  );
}

