export function canViewerAccessNewsStoryPage(input: {
  isUserCreated: boolean;
  publishStatus: PublishStatus;
  ownerId: string | null;
  viewerUserId: string | null;
  newsRequestSuccess: boolean;
}): boolean {
  if (!input.isUserCreated && input.newsRequestSuccess) {
    return true;
